def solution(num, k):
    num = str(num)
    for i in range(len(num)):
        if k == int(num[i]):
            return i + 1
    return -1

def solution(dot):
    onetwothree = range(1, 4)
    for i in onetwothree:
        d1 = (dot[i][0] - dot[0][0]) / (dot[i][1] - dot[0][1])
        a, b = [j for j in onetwothree if j != i]
        d2 = (dot[a][0] - dot[b][0]) / (dot[a][1] - dot[b][1])
        if d1 == d2:
            return 1
    return 0

def solution(lines):
    x = [0] * 200
    for a, b in lines:
        for j in range(a, b):
            x[j - 100] += 1
    return sum(1 for i in x if i > 1)

def solution(board):
    n = len(board)
    danger = [(i, j) for i in range(-1, 2) for j in range(-1, 2) if i or j]
    for i in range(n):
        for j in range(n):
            if board[i][j] == 1:
                for di, dj in danger:
                    if 0 <= i + di < n and 0 <= j + dj < n and board[i + di][j + dj] == 0:
                        board[i + di][j + dj] = 2
    return sum(1 for i in range(n) for j in range(n) if board[i][j] == 0)
